import {useState} from 'react';import {createRoot} from 'react-dom/client';
import {WorkforcePerformanceField} from '../../components/workforce-performance';
const filters={country:'all',org:'all',level:'all'},base={source:'employee_snapshots.performance_rating',snapshotDate:'2026-09-30',reviewPeriod:'2026 YTD',periodKind:'ytd',filters,status:'available',counts:{population:70,ratings:[10,10,10,10,10],notRated:10,unavailable:10}};
function Fixture(){const [mode,setMode]=useState('available');return <main className="mx-auto max-w-4xl p-6"><label>Test response<select value={mode} onChange={e=>setMode(e.target.value)}>{['available','missing','suppressed','changed filter','loading','malformed'].map(m=><option key={m}>{m}</option>)}</select></label><WorkforcePerformanceField value={mode==='missing'?null:mode==='suppressed'?{...base,status:'suppressed',counts:null}:mode==='malformed'?{...base,employee_id:123}:base} filters={mode==='changed filter'?{...filters,country:'US'}:filters} selectedContext={{country:mode==='changed filter'?'United States':'Global workforce',businessUnit:'All business units',level:'All levels'}} loading={mode==='loading'}/></main>}
createRoot(document.getElementById('root')!).render(<Fixture/>);
